1	// andesim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / cycle
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <cstdlib>
11	#include <exception>
12	#include <string>
13	#include <string_view>
14	
15	#include "cli.hpp"
16	#include "dev_mode.hpp"
17	#include "repo_root.hpp"
18	
19	namespace andes_sim {
20	int cmd_list(const Cli& cli);
21	int cmd_doctor(const Cli& cli);
22	int cmd_run(const Cli& cli);
23	}  // namespace andes_sim
24	
25	namespace {
26	
27	using andes_sim::Cli;
28	using andes_sim::cmd_doctor;
29	using andes_sim::cmd_list;
30	using andes_sim::cmd_run;
31	using andes_sim::is_dev_mode;
32	
33	// Known command names. run/list/doctor get handlers as each feature lands; the
34	// rest are stable slots for unfinished ROADMAP features, kept here so `find`
35	// routes them to the "not yet implemented" stub rather than "unknown command",
36	// while never appearing in `--help` (print_usage renders only the
37	// run/list/doctor blocks, so the product never advertises half-built work).
38	// Developer build/test/state-diff tooling lives in scripts/, not the binary.
39	// Display strings (briefs, modes, options) live in the help model below.
40	struct Subcommand {
41	  std::string_view name;
42	};
43	
44	constexpr Subcommand kSubcommands[] = {
45	    {"run"},     {"list"},   {"doctor"},
46	    {"profile"}, {"cluster"}, {"estimate"},
47	};
48	
49	const Subcommand* find(std::string_view name) {
50	  for (const Subcommand& s : kSubcommands)
51	    if (s.name == name) return &s;
52	  return nullptr;
53	}
54	
55	// ---- help model: the user-facing surface rendered as a command tree --------
56	//
57	// `run`'s two subcommand groups -- the modes (the composition axis) ...
58	struct ModeRow {
59	  const char* name;
60	  const char* brief;
61	};
62	constexpr ModeRow kRunModes[] = {
63	    {"fast", "QEMU only -- functional, full speed"},
64	    {"cycle", "one cycle-accurate engine, from reset"},
65	    {"hybrid", "QEMU fast-forwards, then vsim measures the ROI"},
66	};
67	
68	// `list`'s targets. `fixtures` (internal test ELFs) is a developer target,
69	// shown only under ANDESIM_DEV; the product lists user-facing models/engines.
70	struct TargetRow {
71	  const char* name;
72	  const char* brief;
73	  bool dev;
74	};
75	constexpr TargetRow kListTargets[] = {
76	    {"models", "the modes and their engines", false},
77	    {"engines", "discovered cycle-accurate engines", false},
78	    {"fixtures", "internal test ELFs (developer target)", true},
79	};
